@push('styles')
<style>
.role-page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:26px}.role-page-head h1{margin:0 0 7px}.role-page-head p{max-width:680px;margin:0;color:var(--muted);line-height:1.55}.role-section{margin-top:30px}.role-section-head{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:14px}.role-section-head h2{margin:0;font-size:20px}.role-section-head p{margin:5px 0 0;color:var(--muted);font-size:13px}.role-section-count{padding:5px 10px;border-radius:999px;background:var(--pale);color:var(--green);font-size:12px;font-weight:800;white-space:nowrap}.role-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.role-card{min-width:0;display:flex;flex-direction:column;background:#fff;border:1px solid var(--border);border-radius:14px;box-shadow:0 3px 14px #26465308;overflow:hidden}.role-card-head{display:flex;align-items:flex-start;gap:13px;padding:20px 20px 16px}.role-card-icon{flex:0 0 42px;width:42px;height:42px;display:grid;place-items:center;border-radius:10px;background:var(--pale);color:var(--green);font-size:12px;font-weight:900;letter-spacing:.05em}.role-card-icon svg{width:21px;height:21px;stroke-width:1.9}.role-card-title{min-width:0;flex:1}.role-card-title h3{margin:1px 0 5px;font-size:18px;overflow-wrap:anywhere}.role-card-title p{margin:0;color:var(--muted);font-size:12px;line-height:1.45}.role-badges{display:flex;flex-wrap:wrap;gap:7px;padding:0 20px 16px}.role-badge{display:inline-flex;align-items:center;padding:5px 9px;border-radius:999px;background:var(--bg);border:1px solid var(--border);color:#475569;font-size:11px;font-weight:700}.role-badge.scope{background:#eef7fa;color:#285f72;border-color:#c5e0e9}.role-access-summary{margin:0 20px 18px;padding:15px;border:1px solid var(--border);border-radius:10px;background:#fbfcfc}.role-access-count{display:flex;align-items:baseline;gap:7px;margin-bottom:11px}.role-access-count strong{font-size:23px;line-height:1;color:var(--text)}.role-access-count span{color:var(--muted);font-size:12px}.role-module-badges{display:flex;flex-wrap:wrap;gap:7px}.role-module-badges span{display:inline-flex;align-items:center;gap:6px;padding:6px 8px;border-radius:7px;background:var(--pale);color:#076047;font-size:11px;font-weight:700}.role-module-badges strong{display:grid;place-items:center;min-width:19px;height:19px;padding:0 5px;border-radius:99px;background:#fff;color:var(--green);font-size:10px}.role-no-access{margin:0;color:var(--muted);font-size:13px}.role-permission-details{margin-top:13px;border-top:1px solid var(--border);padding-top:11px}.role-permission-details summary{color:var(--green);cursor:pointer;font-size:12px;font-weight:800;list-style-position:inside}.role-permission-groups{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:13px}.role-permission-groups section{min-width:0}.role-permission-groups h4{margin:0 0 6px;font-size:12px}.role-permission-groups ul{margin:0;padding-left:17px;color:#475569;font-size:11px;line-height:1.55}.role-card-footer{display:flex;align-items:center;justify-content:flex-end;gap:10px;margin-top:auto;padding:15px 20px;border-top:1px solid var(--border);background:var(--bg)}.role-card-footer .btn{min-height:38px;padding:8px 12px;font-size:12px}.role-preset .role-card-icon{background:var(--gold-pale);color:#805d16}.role-empty{padding:34px;border:1px dashed #b9c8c4;border-radius:13px;background:#fff;text-align:center;color:var(--muted)}.role-pagination{margin-top:18px}.role-form-card{overflow:hidden;background:#fff;border:1px solid var(--border);border-radius:14px;box-shadow:0 3px 14px #26465308}.role-form-intro{padding:22px;border-bottom:1px solid var(--border)}.role-form-intro .employee-form-grid{max-width:900px}.role-help{max-width:900px;margin:15px 0 0;padding:12px 14px;border-left:3px solid var(--gold);border-radius:7px;background:var(--gold-pale);color:#6f541b;font-size:12px;line-height:1.55}.role-permission-selector{margin:0;padding:0;border:0}.role-selector-toolbar{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 22px;border-bottom:1px solid var(--border);background:var(--bg)}.role-selector-toolbar legend{float:none;width:auto;margin:0;font-size:19px;font-weight:800}.role-selector-toolbar p{margin:4px 0 0;color:var(--muted);font-size:12px}.role-selector-actions{display:flex;align-items:center;justify-content:flex-end;flex-wrap:wrap;gap:8px}.role-selector-actions span{margin-right:4px;color:var(--muted);font-size:12px}.role-selector-actions span strong{color:var(--green);font-size:16px}.role-selector-actions button,.role-permission-group-head button{padding:6px 9px;border:1px solid var(--border);border-radius:7px;background:#fff;color:var(--green);font-size:11px;font-weight:750;cursor:pointer}.role-selector-actions button:hover,.role-permission-group-head button:hover{border-color:var(--green);background:var(--pale)}.role-permission-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;padding:20px 22px}.role-permission-group{min-width:0;padding:16px;border:1px solid var(--border);border-radius:11px;background:#fff}.role-permission-group.has-selection{border-color:#94cdbb;box-shadow:inset 3px 0 var(--green)}.role-permission-group-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:13px}.role-permission-group-head h2{margin:0 0 4px;font-size:15px}.role-permission-group-head p{margin:0;color:var(--muted);font-size:11px;line-height:1.45}.role-permission-group-head button{flex:0 0 auto}.role-permission-options{display:grid;gap:7px}.role-permission-option{display:flex;align-items:flex-start;gap:10px;margin:0;padding:10px;border:1px solid #e3e9e7;border-radius:8px;background:#fbfcfc;color:#334155;font-size:12px;font-weight:600;line-height:1.4;cursor:pointer}.role-permission-option:hover{border-color:#94cdbb;background:var(--pale)}.role-permission-option:has(input:checked){border-color:#74bba5;background:var(--pale);color:#075b44}.role-permission-option input{flex:0 0 auto;width:17px;height:17px;margin-top:1px;accent-color:var(--green)}.role-permission-option[hidden]{display:none}.role-form-footer{display:flex;justify-content:flex-end;gap:10px;padding:18px 22px;border-top:1px solid var(--border);background:var(--bg)}
.role-permission-selector{display:block}.role-selector-toolbar h2{margin:0;font-size:19px;font-weight:800}.role-system-note{display:grid;gap:5px;margin:0 20px 18px;padding:15px;border:1px solid #efd69f;border-radius:10px;background:var(--gold-pale)}.role-system-note strong{color:#6f541b;font-size:14px}.role-system-note span{color:#765f2d;font-size:12px;line-height:1.5}
@media(max-width:900px){.role-grid,.role-permission-grid{grid-template-columns:1fr}}@media(max-width:650px){.role-page-head,.role-section-head,.role-selector-toolbar,.role-permission-group-head{align-items:flex-start;flex-direction:column}.role-page-head .btn{width:100%}.role-selector-actions{justify-content:flex-start}.role-permission-groups{grid-template-columns:1fr}.role-form-footer{flex-direction:column-reverse}.role-form-footer .btn{width:100%}}
</style>
@endpush
